import express, { Express } from 'express';
import { PlaceOrderUseCase } from '../application/PlaceOrderUseCase';
import { UpdateOrderStateUseCase } from '../application/UpdateOrderStateUseCase';
import { CancelOrderUseCase } from '../application/CancelOrderUseCase';
import { ListOrdersByStateUseCase } from '../application/ListOrdersByStateUseCase';
import { GetStockLevelsUseCase } from '../application/GetStockLevelsUseCase';
import { OrderController } from './OrderController';
import { ProductController } from './ProductController';
import { InMemoryOrderRepository } from './InMemoryOrderRepository';
import { InMemoryProductRepository } from './InMemoryProductRepository';
import { Product } from '../domain/Product';
import { Quantity } from '../domain/Quantity';

export function createApp(): Express {
  const app = express();
  app.use(express.json());

  const orderRepository = new InMemoryOrderRepository();
  const productRepository = new InMemoryProductRepository();

  initializeProducts(productRepository);

  const placeOrderUseCase = new PlaceOrderUseCase(orderRepository, productRepository);
  const updateOrderStateUseCase = new UpdateOrderStateUseCase(orderRepository);
  const cancelOrderUseCase = new CancelOrderUseCase(orderRepository, productRepository);
  const listOrdersByStateUseCase = new ListOrdersByStateUseCase(orderRepository);
  const getStockLevelsUseCase = new GetStockLevelsUseCase(productRepository);

  const orderController = new OrderController(
    placeOrderUseCase,
    updateOrderStateUseCase,
    cancelOrderUseCase,
    listOrdersByStateUseCase,
  );

  const productController = new ProductController(getStockLevelsUseCase);

  app.post('/orders', orderController.placeOrder);
  app.patch('/orders/:orderId/state', orderController.updateOrderState);
  app.post('/orders/:orderId/cancel', orderController.cancelOrder);
  app.get('/orders', orderController.listByState);
  app.get('/products/stock', productController.getStockLevels);

  return app;
}

function initializeProducts(productRepository: InMemoryProductRepository): void {
  const products = [
    { id: 'PROD-001', name: 'Laptop', stock: 10 },
    { id: 'PROD-002', name: 'Mouse', stock: 50 },
    { id: 'PROD-003', name: 'Keyboard', stock: 30 },
    { id: 'PROD-004', name: 'Monitor', stock: 5 },
  ];

  for (const p of products) {
    const product = Product.create(p.id, p.name, Quantity.create(p.stock));
    productRepository.save(product);
  }
}

